    "content": "* {\n  box-sizing: border-box;\n}\n\nhtml,\nbody {\n  margin: 0;\n  padding: 0;\n  width: 100%;\n  height: 100%;\n  background: #02040a;\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\",\n    sans-serif;\n  color: #f5f5f5;\n}\n\n.topbar {\n  height: 52px;\n  padding: 8px 16px;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  gap: 3px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n  background: radial-gradient(circle at left top, #10192e, #050710);\n}\n\n.topbar .title {\n  font-size: 15px;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  opacity: 0.9;\n}\n\n.topbar .subtitle {\n  font-size: 12px;\n  opacity: 0.75;\n}\n\n#world {\n  display: block;\n  width: 100vw;\n  height: calc(100vh - 52px - 90px);\n}\n\n.log {\n  height: 90px;\n  padding: 8px 12px;\n  overflow: auto;\n  font-size: 11px;\n  line-height: 1.4;\n  border-top: 1px solid rgba(255, 255, 255, 0.06);\n  background: linear-gradient(to bottom, #050710, #020309);\n}\n\n.log div {\n  white-space: nowrap;\n}\n"
