    "content": "/* ======================================================\n   VaFT UI 2.0\n   Bráška Hlava\n====================================================== */\n\n:root{\n\n  --bg:#2A2A2A;\n  --card:#343434;\n  --card-light:#3A3A3A;\n\n  --border:#4A4A4A;\n\n  --text:#FFFFFF;\n  --muted:#B0B0B0;\n\n  --accent:#FF8A00;\n\n  --button:#FFFFFF;\n  --buttonText:#222222;\n\n  --radius:22px;\n\n}\n\n/* ====================================================== */\n\n*{\n    box-sizing:border-box;\n    margin:0;\n    padding:0;\n}\n\nbody{\n\n    background:\n    linear-gradient(\n        180deg,\n        #323232,\n        #262626\n    );\n\n    color:var(--text);\n\n    font-family:\n    system-ui,\n    -apple-system,\n    BlinkMacSystemFont,\n    \"SF Pro Display\",\n    sans-serif;\n\n    width:100%;\n    min-height:100dvh;\n\n    overflow:hidden;\n\n    touch-action:manipulation;\n\n    -webkit-tap-highlight-color:transparent;\n\n    padding:\n      calc(env(safe-area-inset-top) + 18px)\n      18px\n      calc(env(safe-area-inset-bottom) + 18px);\n\n}\n\n/* ====================================================== */\n\n.wrapper{\n\n    max-width:900px;\n\n    width:100%;\n\n    margin:auto;\n\n}\n\n/* ====================================================== */\n\n.hero{\n\n    display:flex;\n    flex-direction:column;\n    align-items:center;\n\n    gap:14px;\n\n    margin-bottom:26px;\n\n}\n\n/* ====================================================== */\n\n#sphere{\n\n    width:140px;\n    height:140px;\n\n    border-radius:50%;\n\n    background:\n    radial-gradient(\n      circle at 35% 35%,\n      #FFFFFF,\n      #CFCFCF 45%,\n      #555555 100%\n    );\n\n    box-shadow:\n    0 0 35px rgba(255,138,0,.45);\n\n    display:flex;\n\n    justify-content:center;\n    align-items:center;\n\n    text-align:center;\n\n    color:#222;\n\n    font-weight:bold;\n\n    transition:.35s;\n\n}\n\n/* ====================================================== */\n\n#log{\n\n    color:var(--muted);\n\n    font-size:.9rem;\n\n}\n\n/* ====================================================== */\n\n.dashboard{\n\n    display:grid;\n\n    gap:18px;\n\n}\n\n@media(min-width:768px){\n\n.dashboard{\n\ngrid-template-columns:\nrepeat(2,1fr);\n\n}\n\n}\n\n/* ====================================================== */\n\n.card{\n\n    background:var(--card);\n\n    border:1px solid var(--border);\n\n    border-radius:var(--radius);\n\n    padding:22px;\n\n    box-shadow:\n    0 12px 30px rgba(0,0,0,.28);\n\n}\n\n/* ====================================================== */\n\n.card h2{\n\n    font-size:2rem;\n\n    margin-bottom:18px;\n\n    color:white;\n\n}\n\n/* ====================================================== */\n\n.stat{\n\n    display:flex;\n\n    justify-content:space-between;\n\n    margin:12px 0;\n\n}\n\n.stat span:first-child{\n\n    color:var(--muted);\n\n}\n\n/* ====================================================== */\n\nbutton{\n\n    background:var(--button);\n\n    color:var(--buttonText);\n\n    border:none;\n\n    border-radius:14px;\n\n    padding:13px 18px;\n\n    font-size:15px;\n\n    font-weight:600;\n\n    cursor:pointer;\n\n    transition:.25s;\n\n    margin-top:8px;\n    margin-right:8px;\n\n}\n\nbutton:hover{\n\n    background:var(--accent);\n\n    color:white;\n\n    transform:translateY(-2px);\n\n}\n\n/* ====================================================== */\n\nbutton:disabled{\n\n    opacity:.55;\n\n    cursor:not-allowed;\n\n}\n\n/* ====================================================== */\n\nhr{\n\n    border:none;\n\n    height:1px;\n\n    background:var(--border);\n\n    margin:18px 0;\n\n}\n\n/* ====================================================== */\n\npre{\n\n    color:var(--muted);\n\n    white-space:pre-wrap;\n\n    line-height:1.6;\n\n}\n\n/* ====================================================== */\n\ninput[type=file]{\n\n    display:none;\n\n}\n\n/* ====================================================== */\n\n#seznamSouboru{\n\n    margin-top:15px;\n\n    color:var(--muted);\n\n}\n\n#nahledObrazku{\n\n    width:100%;\n\n    margin-top:15px;\n\n    border-radius:18px;\n\n}\n\n/* ====================================================== */\n\n::selection{\n\n    background:var(--accent);\n\n    color:white;\n\n}\n\n.signalSphere{\n\nposition:relative;\n\noverflow:hidden;\n\n}\n\n.sphereOverlay{\n\nposition:absolute;\n\ntop:14px;\n\nleft:14px;\n\nright:14px;\n\npointer-events:none;\n\n}\n\n.sphereName{\n\nfont-size:20px;\n\nfont-weight:700;\n\ncolor:#ffffff;\n\n}\n\n.sphereState{\n\nmargin-top:6px;\n\ncolor:#7dff93;\n\nfont-size:14px;\n\n}\n\n.spherePulse{\n\nmargin-top:10px;\n\nfont-size:13px;\n\ncolor:#bdbdbd;\n\nanimation:pulseSphere 2s infinite;\n\n}\n\n@keyframes pulseSphere{\n\n0%{opacity:.35;}\n\n50%{opacity:1;}\n\n100%{opacity:.35;}\n\n}\n\n.signalSphere canvas{\n\n    display:block;\n\n    width:100%;\n\n    height:100%;\n\n    image-rendering:auto;\n\n    touch-action:none;\n\n}\n\n.signalSphere{\n\n    position:relative;\n\n    overflow:hidden;\n\n    width:100%;\n\n    aspect-ratio:1/1;\n\n    min-height:320px;\n\n}"
