      ".ring-v3__middle",
      ".ring-v3__inner",
      ".ring-v3__latitude",
      ".ring-v3__longitude",
      ".ring-v3__dash",
      ".ring-v3__star",
      ".cht-room-orbit__rooms",
      ".cht-room",
