    "content": ":root{\n  --revia-zlata:#ffe2ad;\n  --revia-zlata-tmava:#c79b33;\n  --revia-pozadi:rgba(7,6,10,.94);\n}\n\n.srOnly{\n  position:absolute;\n  width:1px;\n  height:1px;\n  padding:0;\n  margin:-1px;\n  overflow:hidden;\n  clip:rect(0,0,0,0);\n  white-space:nowrap;\n  border:0;\n}\n\n.openReviaPanel{\n  position:fixed;\n  z-index:28;\n  bottom:max(46px,calc(env(safe-area-inset-bottom) + 34px));\n  left:max(15px,env(safe-area-inset-left));\n  display:flex;\n  align-items:center;\n  gap:7px;\n  padding:7px 10px 7px 7px;\n  border:1px solid rgba(255,226,173,.42);\n  border-radius:999px;\n  background:linear-gradient(145deg,rgba(33,22,18,.94),rgba(5,5,9,.94));\n  color:var(--revia-zlata);\n  box-shadow:0 0 22px rgba(226,171,84,.2), inset 0 0 14px rgba(255,222,173,.08);\n  font-size:11px;\n  font-weight:800;\n  letter-spacing:.04em;\n  cursor:pointer;\n  -webkit-tap-highlight-color:transparent;\n}\n\n.openReviaPanel:active{transform:scale(.96)}\n\n.reviaOrb{\n  display:grid;\n  width:25px;\n  height:25px;\n  place-items:center;\n  border:1px solid rgba(255,241,206,.86);\n  border-radius:50%;\n  background:radial-gradient(circle at 32% 28%,#fffaf0 0 8%,#efd18d 35%,#8d4e22 100%);\n  color:#241407;\n  font-size:12px;\n  font-weight:950;\n  box-shadow:0 0 12px rgba(255,220,150,.72);\n}\n\n.reviaPanel{\n  position:fixed;\n  z-index:35;\n  top:max(45px,env(safe-area-inset-top));\n  bottom:max(35px,env(safe-area-inset-bottom));\n  left:max(13px,env(safe-area-inset-left));\n  display:none;\n  width:min(356px,calc(100vw - 26px));\n  min-height:0;\n  flex-direction:column;\n  overflow:hidden;\n  border:1px solid rgba(255,226,173,.38);\n  border-radius:22px;\n  background:\n    radial-gradient(circle at 20% 0%,rgba(210,158,75,.15),transparent 38%),\n    var(--revia-pozadi);\n  box-shadow:0 18px 60px rgba(0,0,0,.62),0 0 38px rgba(207,151,65,.14),inset 0 0 26px rgba(255,220,160,.035);\n  backdrop-filter:blur(18px);\n  -webkit-backdrop-filter:blur(18px);\n}\n\n.reviaPanel.is-open{display:flex}\n.openReviaPanel[aria-hidden=\"true\"]{display:none}\n\n.reviaTop{\n  display:grid;\n  grid-template-columns:auto minmax(0,1fr) auto;\n  align-items:center;\n  gap:9px;\n  padding:11px 12px 10px;\n  border-bottom:1px solid rgba(255,226,173,.14);\n}\n\n.reviaMode,\n.reviaClose,\n.reviaShortcuts button,\n.reviaForm button{\n  border:1px solid rgba(255,226,173,.24);\n  color:var(--revia-zlata);\n  cursor:pointer;\n  -webkit-tap-highlight-color:transparent;\n}\n\n.reviaMode{\n  display:flex;\n  align-items:center;\n  gap:5px;\n  min-height:30px;\n  padding:5px 8px;\n  border-radius:12px;\n  background:rgba(255,220,160,.08);\n  font-size:10px;\n  font-weight:800;\n}\n\n.reviaTitle{min-width:0}\n.reviaTitle strong,.reviaTitle small{display:block}\n.reviaTitle strong{font-size:13px;letter-spacing:.04em}\n.reviaTitle small{margin-top:2px;overflow:hidden;color:rgba(255,240,207,.56);font-size:9px;text-overflow:ellipsis;white-space:nowrap}\n\n.reviaClose{\n  display:grid;\n  width:30px;\n  height:30px;\n  padding:0;\n  place-items:center;\n  border-radius:10px;\n  background:rgba(255,220,160,.07);\n  font-size:20px;\n  line-height:1;\n}\n\n.reviaShortcuts{display:flex;gap:6px;padding:9px 12px;overflow-x:auto;border-bottom:1px solid rgba(255,226,173,.09)}\n.reviaShortcuts button{flex:0 0 auto;padding:6px 8px;border-radius:999px;background:rgba(255,220,160,.06);font-size:10px;font-weight:750}\n.reviaShortcuts button:active,.reviaMode:active,.reviaClose:active{background:rgba(255,220,160,.2);transform:scale(.96)}\n\n.reviaLog{display:flex;min-height:0;flex:1;flex-direction:column;gap:8px;padding:11px 12px;overflow:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}\n.reviaMessage{max-width:92%;padding:8px 10px;border:1px solid rgba(255,226,173,.13);border-radius:14px;color:rgba(255,248,229,.9);font-size:11px;line-height:1.42;overflow-wrap:anywhere}\n.reviaMessage strong{display:block;margin-bottom:3px;color:var(--revia-zlata);font-size:9px;letter-spacing:.07em;text-transform:uppercase}\n.reviaMessage-user{align-self:flex-end;border-color:rgba(255,226,173,.28);background:rgba(179,112,42,.16)}\n.reviaMessage-revia{align-self:flex-start;background:rgba(255,255,255,.04)}\n\n.reviaForm{display:grid;grid-template-columns:minmax(0,1fr) 38px;gap:7px;padding:9px 12px;border-top:1px solid rgba(255,226,173,.12)}\n.reviaForm textarea{width:100%;min-height:40px;max-height:100px;padding:9px 10px;resize:vertical;border:1px solid rgba(255,226,173,.18);border-radius:13px;outline:none;background:rgba(0,0,0,.24);color:#fff3d7;font-size:12px;line-height:1.35}\n.reviaForm textarea:focus{border-color:rgba(255,226,173,.6);box-shadow:0 0 0 3px rgba(255,210,130,.09)}\n.reviaForm button{align-self:stretch;border-radius:13px;background:linear-gradient(145deg,#d79a44,#7f3d1c);color:#281306;font-size:19px;font-weight:950}\n.reviaState{margin:0;padding:0 12px 10px;color:rgba(255,240,207,.48);font-size:9px;line-height:1.32}\n\n@media (max-height:440px){\n  .reviaPanel{top:34px;bottom:26px;width:min(330px,calc(100vw - 26px))}\n  .reviaTop{padding:8px 10px}\n  .reviaShortcuts{padding:6px 10px}\n  .reviaLog{gap:6px;padding:8px 10px}\n  .reviaMessage{padding:6px 8px;font-size:10px}\n  .reviaForm{padding:7px 10px}\n  .reviaState{padding:0 10px 7px}\n}\n"
