    "content": ":root{color-scheme:dark;--bg:#0b0805;--ink:#fff0cf;--muted:#b8a68b;--gold:#efc16d;--line:rgba(239,193,109,.25);--panel:rgba(21,15,10,.9);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\n*{box-sizing:border-box} body{margin:0;min-height:100dvh;background:radial-gradient(circle at 50% 38%,#3a2916 0%,#120d08 34%,var(--bg) 75%);color:var(--ink)}\nbutton,input,textarea{font:inherit}.shell{min-height:100dvh;padding:max(18px,env(safe-area-inset-top)) max(16px,env(safe-area-inset-right)) max(20px,env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left));max-width:980px;margin:auto}.top{display:flex;align-items:end;justify-content:space-between;gap:16px}.eyebrow{margin:0;color:var(--gold);letter-spacing:.16em;font-size:12px}.top h1{margin:2px 0 0;font-size:clamp(24px,5vw,38px);letter-spacing:.03em}.top h1 span{color:var(--gold)}.connectionState{padding:7px 10px;border:1px solid var(--line);border-radius:999px;color:var(--gold);font-size:11px;white-space:nowrap}.intro{max-width:700px;color:var(--muted);line-height:1.45}\n.ways{display:flex;gap:7px;overflow:auto;padding:5px 0 11px}.way{flex:0 0 auto;display:flex;gap:6px;align-items:center;padding:8px 10px;border:1px solid var(--line);border-radius:14px;background:rgba(0,0,0,.18);color:var(--muted);font-size:11px;font-weight:800;cursor:pointer}.way b{display:grid;place-items:center;width:18px;height:18px;border:1px solid var(--line);border-radius:50%;color:var(--gold);font-size:10px}.way.is-active{background:rgba(239,193,109,.12);color:var(--ink);border-color:rgba(239,193,109,.6)}\n.core{display:grid;grid-template-columns:minmax(260px,.9fr) minmax(0,1.1fr);gap:12px}.memoryPanel,.wayPanel{min-height:0;padding:14px;border:1px solid var(--line);border-radius:20px;background:var(--panel);box-shadow:inset 0 0 28px rgba(239,193,109,.03),0 15px 45px rgba(0,0,0,.24)}.panelTop,.pulseHead{display:flex;justify-content:space-between;align-items:center;gap:8px}.panelTop small,.pulseHead span{display:block;color:var(--muted);font-size:10px}.memoryPanel label,.wayContent label{display:block;margin-top:12px;color:var(--muted);font-size:11px}.memoryPanel textarea,.wayContent textarea,.wayContent input,.wayContent select{display:block;width:100%;margin-top:5px;padding:9px 10px;border:1px solid var(--line);border-radius:12px;outline:0;background:rgba(0,0,0,.3);color:var(--ink);resize:vertical}.actions,.routeActions{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}button,.fileButton{padding:8px 10px;border:1px solid var(--line);border-radius:11px;background:rgba(255,255,255,.04);color:var(--ink);font-size:11px;font-weight:800;cursor:pointer}.primary{background:linear-gradient(135deg,#f6d58b,#a65922);border-color:transparent;color:#281405}.quiet{padding:5px 7px;color:var(--muted);font-size:10px}.fileButton input{position:absolute;width:1px;height:1px;opacity:0}.memoryLog{display:grid;gap:7px;max-height:280px;margin-top:13px;overflow:auto}.memoryEntry{padding:9px;border:1px solid rgba(239,193,109,.12);border-radius:12px;background:rgba(0,0,0,.16);font-size:11px;line-height:1.4}.memoryEntry small{display:block;margin-bottom:3px;color:var(--gold);font-size:9px}.wayContent h2{margin:0;color:var(--gold);font-size:16px}.wayContent p{color:var(--muted);font-size:12px;line-height:1.45}.hint{padding:9px;border-left:2px solid var(--gold);background:rgba(239,193,109,.06);color:#dfca9e;font-size:11px;line-height:1.45}.commandGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(115px,1fr));gap:7px;margin-top:10px}.command{min-height:60px;text-align:left}.command span,.command small{display:block}.command small{margin-top:4px;color:var(--muted);font-size:9px}.lightPulse{display:grid;place-items:center;min-height:130px;margin:11px 0;border:1px solid rgba(239,193,109,.55);border-radius:16px;background:repeating-linear-gradient(90deg,#171006 0 5px,#f6d58b 5px 8px,#171006 8px 13px);color:#171006;font-weight:950;letter-spacing:.14em;text-align:center}.pulsePreview{margin-top:13px;padding-top:12px;border-top:1px solid rgba(239,193,109,.15)}pre{max-height:185px;margin:8px 0 0;overflow:auto;white-space:pre-wrap;word-break:break-word;color:#e8d5ae;font-size:10px;line-height:1.38}.status{margin:12px 2px 0;color:var(--muted);font-size:10px;line-height:1.35}\n.selfCleaner{margin-top:13px;padding:11px;border:1px solid rgba(239,193,109,.16);border-radius:16px;background:linear-gradient(135deg,rgba(239,193,109,.08),rgba(0,0,0,.1))}.selfCleaner p{margin:7px 0 0;color:var(--muted);font-size:10px;line-height:1.4}.seedLog{display:grid;gap:6px;max-height:116px;margin-top:10px;overflow:auto}.seedItem{padding:7px;border:1px solid rgba(239,193,109,.12);border-radius:11px;background:rgba(0,0,0,.18);font-size:10px;line-height:1.35}.seedItem b{display:block;color:var(--gold);font-size:10px}.seedItem small{display:block;margin-top:3px;color:var(--muted);font-size:9px}.memoryLog{max-height:220px}\n@media(max-width:680px){.core{grid-template-columns:1fr}.shell{padding-top:max(12px,env(safe-area-inset-top))}.memoryLog{max-height:170px}}@media(max-height:470px) and (orientation:landscape){.shell{padding-top:8px;padding-bottom:8px}.intro{margin:6px 0}.memoryPanel,.wayPanel{padding:10px}.memoryLog{max-height:120px}.lightPulse{min-height:80px}.seedLog{max-height:84px}}\n.transferActions{margin-top:13px}.transferList{display:grid;gap:7px;max-height:310px;margin-top:13px;overflow:auto}.transferListHead{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:2px 1px}.transferListHead strong{color:var(--gold);font-size:13px}.transferListHead small,.transferEmpty{color:var(--muted);font-size:10px;line-height:1.4}.transferEmpty{margin:0;padding:10px;border:1px dashed rgba(239,193,109,.18);border-radius:12px}.transferItem{display:grid;grid-template-columns:46px minmax(0,1fr) auto;align-items:center;gap:8px;padding:7px;border:1px solid rgba(239,193,109,.14);border-radius:13px;background:rgba(0,0,0,.18)}.transferItem img,.fileMark{display:grid;width:46px;height:46px;place-items:center;border-radius:9px;object-fit:cover;background:rgba(239,193,109,.12);color:var(--gold);font-size:18px}.transferItemBody{min-width:0}.transferItemBody b,.transferItemBody small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.transferItemBody b{font-size:11px}.transferItemBody small{margin-top:3px;color:var(--muted);font-size:9px}.transferItemActions{display:flex;flex-direction:column;gap:4px}.transferItemActions button{padding:5px 6px;font-size:9px}.bridgeTitle{margin:17px 0 0;color:var(--gold);font-size:13px}\n"
