    "content": "{\n  \"name\": \"CHT 360°‰.\",\n  \"short_name\": \"CHT 360°‰.\",\n  \"lang\": \"cs\",\n  \"start_url\": \"./\",\n  \"scope\": \"./\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#050403\",\n  \"theme_color\": \"#17100b\",\n  \"orientation\": \"landscape\"\n}\n"
