    "content": ":root {\n  color-scheme: dark;\n  --bg: #090806;\n  --panel: rgba(20, 17, 12, .88);\n  --panel-deep: rgba(10, 9, 7, .96);\n  --line: rgba(255, 226, 173, .18);\n  --gold: #ffe2ad;\n  --gold-soft: #fff0c5;\n  --gold-deep: #c79b33;\n  --text: #fff8e8;\n  --muted: #c9bea7;\n  --quiet: #928778;\n  --good: #cbe69b;\n  --warn: #ffcb86;\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n* { box-sizing: border-box; }\n\nhtml { background: var(--bg); }\n\nbody {\n  min-width: 320px;\n  min-height: 100vh;\n  margin: 0;\n  color: var(--text);\n  background:\n    radial-gradient(circle at 7% 6%, rgba(199, 155, 51, .22), transparent 26rem),\n    radial-gradient(circle at 88% 42%, rgba(255, 226, 173, .09), transparent 31rem),\n    linear-gradient(135deg, #070604, #16120a 52%, #080706);\n}\n\nbutton, textarea, a { font: inherit; }\nbutton { cursor: pointer; }\nbutton, a { -webkit-tap-highlight-color: transparent; }\n\nbutton:focus-visible,\ntextarea:focus-visible,\na:focus-visible {\n  outline: 2px solid var(--gold);\n  outline-offset: 3px;\n}\n\n.app-shell {\n  width: min(1040px, 100%);\n  margin: 0 auto;\n  padding:\n    max(18px, env(safe-area-inset-top))\n    clamp(14px, 3vw, 42px)\n    max(22px, env(safe-area-inset-bottom));\n}\n\n.topbar {\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  gap: 12px;\n  min-height: 54px;\n}\n\n.back-link,\n.quiet-button,\n.route-actions a {\n  display: inline-flex;\n  min-height: 38px;\n  align-items: center;\n  justify-content: center;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  color: var(--gold);\n  background: rgba(255, 255, 255, .025);\n  font-size: .77rem;\n  font-weight: 820;\n  text-decoration: none;\n}\n\n.back-link { justify-self: start; gap: 7px; }\n.quiet-button { color: var(--gold-soft); }\n\n.back-link:hover,\n.quiet-button:hover,\n.route-actions a:hover {\n  border-color: rgba(255, 226, 173, .58);\n  background: rgba(255, 226, 173, .11);\n}\n\n.brand { min-width: 0; text-align: center; }\n\n.brand p,\n.eyebrow {\n  margin: 0;\n  color: var(--gold-deep);\n  font-size: .66rem;\n  font-weight: 880;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n\n.brand strong {\n  display: block;\n  margin-top: 3px;\n  color: var(--gold-soft);\n  font-size: .73rem;\n  letter-spacing: .06em;\n}\n\n.state-pill {\n  justify-self: end;\n  padding: 6px 8px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  color: var(--muted);\n  background: rgba(0, 0, 0, .18);\n  font-size: .67rem;\n  font-weight: 800;\n}\n\n.state-pill.is-offline { color: var(--warn); }\n.state-pill.is-ready { color: var(--good); }\n\n.hero-card,\n.overview-card,\n.talk-card,\n.route-card {\n  margin-top: 17px;\n  border: 1px solid var(--line);\n  border-radius: 23px;\n  background: linear-gradient(145deg, var(--panel), var(--panel-deep));\n  box-shadow: 0 18px 60px rgba(0, 0, 0, .27);\n}\n\n.hero-card {\n  display: grid;\n  grid-template-columns: minmax(0, 1.4fr) minmax(220px, .6fr);\n  gap: clamp(18px, 4vw, 45px);\n  padding: clamp(20px, 4.2vw, 48px);\n}\n\nh1,\nh2 {\n  margin: 0;\n  color: var(--gold-soft);\n}\n\nh1 {\n  margin-top: 8px;\n  font-size: clamp(2rem, 5vw, 3.8rem);\n  letter-spacing: -.055em;\n  line-height: .98;\n}\n\nh1 em { color: var(--gold); font-style: normal; }\n\n.hero-card > div > p:not(.eyebrow) {\n  max-width: 650px;\n  margin: 17px 0 0;\n  color: var(--muted);\n  font-size: .95rem;\n  line-height: 1.65;\n}\n\n.honesty-card {\n  align-self: stretch;\n  padding: 17px;\n  border: 1px solid rgba(255, 226, 173, .2);\n  border-radius: 16px;\n  background: rgba(0, 0, 0, .2);\n}\n\n.honesty-card strong { color: var(--gold); font-size: .8rem; }\n\n.honesty-card p {\n  margin: 8px 0 0;\n  color: var(--quiet);\n  font-size: .78rem;\n  line-height: 1.55;\n}\n\n.overview-card,\n.talk-card,\n.route-card { padding: clamp(15px, 2.6vw, 25px); }\n\n.section-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.section-heading h2,\n.route-card h2 {\n  margin-top: 5px;\n  font-size: 1.05rem;\n}\n\n.memory-overview {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 8px;\n  margin-top: 16px;\n}\n\n.memory-tile {\n  min-width: 0;\n  padding: 12px;\n  border: 1px solid rgba(255, 226, 173, .13);\n  border-radius: 14px;\n  background: rgba(0, 0, 0, .16);\n}\n\n.memory-tile strong,\n.memory-tile span,\n.memory-tile small { display: block; }\n\n.memory-tile strong { color: var(--gold); font-size: .78rem; }\n\n.memory-tile span {\n  margin-top: 7px;\n  color: var(--gold-soft);\n  font-size: 1.15rem;\n  font-weight: 880;\n}\n\n.memory-tile small {\n  margin-top: 5px;\n  color: var(--quiet);\n  font-size: .67rem;\n  line-height: 1.35;\n}\n\n.conversation {\n  display: grid;\n  gap: 9px;\n  min-height: 250px;\n  max-height: min(52vh, 520px);\n  margin-top: 16px;\n  overflow-y: auto;\n  padding: 6px 3px 6px 0;\n}\n\n.message {\n  max-width: min(88%, 680px);\n  padding: 11px 12px;\n  border: 1px solid rgba(255, 226, 173, .15);\n  border-radius: 15px;\n  color: var(--muted);\n  background: rgba(0, 0, 0, .2);\n  font-size: .83rem;\n  line-height: 1.52;\n  white-space: pre-wrap;\n}\n\n.message strong {\n  display: block;\n  margin-bottom: 4px;\n  color: var(--gold);\n  font-size: .66rem;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n\n.message.user {\n  justify-self: end;\n  border-color: rgba(199, 155, 51, .34);\n  color: var(--gold-soft);\n  background: rgba(199, 155, 51, .1);\n}\n\n.message.system {\n  border-color: rgba(203, 230, 155, .26);\n}\n\n.quick-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 10px;\n}\n\n.quick-actions button {\n  min-height: 32px;\n  padding: 5px 8px;\n  border: 1px solid rgba(255, 226, 173, .16);\n  border-radius: 10px;\n  color: var(--muted);\n  background: rgba(0, 0, 0, .17);\n  font-size: .7rem;\n  font-weight: 780;\n}\n\n.quick-actions button:hover {\n  border-color: rgba(255, 226, 173, .55);\n  color: var(--gold);\n}\n\n.talk-form {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  gap: 8px;\n  margin-top: 12px;\n}\n\ntextarea {\n  width: 100%;\n  min-width: 0;\n  resize: vertical;\n  padding: 10px;\n  border: 1px solid rgba(255, 226, 173, .18);\n  border-radius: 13px;\n  color: var(--text);\n  background: rgba(3, 3, 2, .5);\n  line-height: 1.42;\n}\n\ntextarea:focus {\n  border-color: rgba(255, 226, 173, .66);\n  box-shadow: 0 0 0 3px rgba(199, 155, 51, .12);\n  outline: none;\n}\n\n.primary-button {\n  align-self: stretch;\n  min-width: 90px;\n  padding: 8px 12px;\n  border: 1px solid rgba(255, 226, 173, .64);\n  border-radius: 13px;\n  color: #201607;\n  background: linear-gradient(135deg, #ffebbf, #d9a94c);\n  font-size: .8rem;\n  font-weight: 900;\n}\n\n.route-card {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.route-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 7px;\n}\n\nfooter {\n  margin: 15px 4px 0;\n  color: var(--quiet);\n  font-size: .7rem;\n  line-height: 1.5;\n  text-align: center;\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n}\n\n@media (max-width: 720px) {\n  .hero-card { grid-template-columns: 1fr; }\n  .memory-overview { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .route-card { display: grid; }\n}\n\n@media (max-width: 480px) {\n  .topbar { grid-template-columns: auto 1fr auto; }\n  .back-link span { display: none; }\n  .brand { text-align: left; }\n  .state-pill { max-width: 74px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .talk-form { grid-template-columns: 1fr; }\n  .primary-button { min-height: 42px; }\n  .memory-overview { grid-template-columns: 1fr 1fr; }\n}"
