    "content": ":root {\n  color-scheme: dark;\n  --ink: #fff1cf;\n  --muted: rgba(255, 237, 196, .66);\n  --gold: #e9b95f;\n  --gold-bright: #ffd98e;\n  --line: rgba(255, 219, 151, .19);\n  --surface: rgba(21, 13, 8, .84);\n  --deep: #050403;\n  font-family: ui-rounded, \"SF Pro Rounded\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n* { box-sizing: border-box; }\n\nhtml, body { min-height: 100%; margin: 0; background: var(--deep); }\n\nbody {\n  color: var(--ink);\n  background:\n    radial-gradient(circle at 78% 7%, rgba(220, 161, 68, .18), transparent 30%),\n    radial-gradient(circle at 12% 50%, rgba(118, 59, 29, .15), transparent 30%),\n    linear-gradient(145deg, #050403, #17100b 52%, #070505);\n}\n\nbutton, input, textarea { font: inherit; }\nbutton { -webkit-tap-highlight-color: transparent; }\n\n.appShell { width: min(1220px, 100%); min-height: 100dvh; margin: 0 auto; padding: max(14px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(24px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left)); }\n\n.topbar, .actions, .editorHead, .summary, .hero { display: flex; align-items: center; }\n.topbar { justify-content: space-between; gap: 14px; min-height: 48px; }\n.titleBlock { flex: 1; min-width: 0; text-align: center; }\nh1, h2, p { margin: 0; }\nh1 { font-size: clamp(18px, 3vw, 28px); letter-spacing: .04em; }\nh2 { font-size: clamp(18px, 2.9vw, 26px); }\n.eyebrow { margin-bottom: 3px; color: var(--gold); font-size: 10px; font-weight: 900; letter-spacing: .13em; text-transform: uppercase; }\n\n.backLink, .quietButton, .mainButton {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 39px;\n  border: 1px solid var(--line);\n  border-radius: 13px;\n  padding: 8px 12px;\n  color: var(--ink);\n  background: rgba(255, 225, 172, .06);\n  font-size: 12px;\n  font-weight: 800;\n  text-decoration: none;\n  cursor: pointer;\n}\n\n.mainButton { border-color: rgba(255, 220, 150, .45); background: linear-gradient(135deg, #a96325, #e5b158); color: #160b05; }\n.mainButton.gold { background: linear-gradient(135deg, #f5cd7c, #b16c25); }\n.mainButton.compact { min-height: 35px; padding: 7px 11px; }\n.fileButton { position: relative; overflow: hidden; }\n.quietButton.danger { color: #ffd0c1; border-color: rgba(255, 134, 104, .32); }\nbutton:disabled { cursor: not-allowed; opacity: .46; }\n\n.hero { justify-content: space-between; gap: 20px; margin-top: 14px; padding: 18px clamp(17px, 4vw, 34px); border: 1px solid var(--line); border-radius: 21px; background: linear-gradient(115deg, rgba(255, 211, 127, .12), rgba(39, 20, 10, .5)); }\n.hero h2 { margin: 8px 0; }\n.hero p:not(.badge) { max-width: 760px; color: var(--muted); font-size: 13px; line-height: 1.52; }\n.badge { display: inline-block; border: 1px solid rgba(255, 215, 134, .34); border-radius: 999px; padding: 4px 8px; color: var(--gold-bright); background: rgba(0,0,0,.16); font-size: 10px; font-weight: 900; letter-spacing: .06em; }\n.heroGlyph { min-width: 76px; color: var(--gold-bright); font-size: clamp(42px, 8vw, 82px); font-weight: 900; text-align: center; text-shadow: 0 0 25px rgba(255, 206, 120, .45); }\n\n.actions { flex-wrap: wrap; gap: 8px; margin: 14px 0 7px; }\n.statusLine { min-height: 20px; color: var(--muted); font-size: 12px; }\n\n.summary { gap: 8px; margin: 12px 0; }\n.summary article { flex: 1; min-width: 0; padding: 11px 12px; border: 1px solid var(--line); border-radius: 15px; background: rgba(17, 10, 6, .56); }\n.summary strong, .summary span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.summary strong { color: var(--gold-bright); font-size: clamp(14px, 2.4vw, 21px); }\n.summary span { margin-top: 2px; color: var(--muted); font-size: 10px; }\n\n.workspace { display: grid; grid-template-columns: minmax(220px, .38fr) minmax(0, 1fr); min-height: min(58dvh, 640px); overflow: hidden; border: 1px solid var(--line); border-radius: 19px; background: rgba(9, 6, 4, .68); }\n.filePane { display: flex; min-width: 0; flex-direction: column; border-right: 1px solid var(--line); }\n.paneHead { padding: 12px; border-bottom: 1px solid var(--line); }\n.searchLabel { display: block; margin-bottom: 5px; color: var(--muted); font-size: 11px; font-weight: 700; }\ninput[type=\"search\"] { width: 100%; border: 1px solid var(--line); border-radius: 10px; padding: 9px 10px; color: var(--ink); background: rgba(255, 242, 209, .05); font-size: 12px; outline: none; }\ninput[type=\"search\"]:focus, textarea:focus { border-color: rgba(255, 213, 127, .7); box-shadow: 0 0 0 3px rgba(219, 157, 61, .14); }\n.fileList { overflow: auto; padding: 7px; overscroll-behavior: contain; }\n.fileItem { display: block; width: 100%; border: 0; border-radius: 9px; padding: 8px 9px; color: var(--muted); background: transparent; text-align: left; font-family: ui-monospace, \"SFMono-Regular\", Menlo, monospace; font-size: 11px; line-height: 1.25; cursor: pointer; word-break: break-word; }\n.fileItem:hover, .fileItem:focus-visible, .fileItem.selected { color: #241508; background: linear-gradient(135deg, #ffe0a0, #d58d3b); outline: none; }\n.fileItem.changed::before { content: \"• \"; color: var(--gold-bright); font-weight: 900; }\n\n.editorPane { display: flex; min-width: 0; flex-direction: column; }\n.editorHead { justify-content: space-between; gap: 12px; padding: 12px 14px; border-bottom: 1px solid var(--line); }\n.selectedPath { overflow: hidden; color: var(--gold-bright); font-family: ui-monospace, \"SFMono-Regular\", Menlo, monospace; font-size: 12px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }\n.fileMeta { margin-top: 4px; color: var(--muted); font-size: 11px; }\n.editorActions { display: flex; flex: 0 0 auto; gap: 6px; }\n.editorEmpty { display: flex; flex: 1; align-items: center; justify-content: center; flex-direction: column; gap: 7px; padding: 22px; color: var(--muted); text-align: center; font-size: 13px; }\n.editorEmpty strong { color: var(--gold-bright); font-size: 20px; }\ntextarea { flex: 1; width: 100%; min-height: 330px; resize: none; border: 0; border-radius: 0; padding: 14px; color: #fff5df; background: rgba(0,0,0,.24); font-family: ui-monospace, \"SFMono-Regular\", Menlo, Consolas, monospace; font-size: 12px; line-height: 1.52; outline: none; }\n\n.notes { margin: 15px 0 2px; padding: 14px 16px; border-left: 2px solid var(--gold); border-radius: 0 14px 14px 0; background: rgba(255, 211, 127, .05); }\n.notes h2 { margin-bottom: 6px; font-size: 15px; }\n.notes p, .dialogHint { color: var(--muted); font-size: 12px; line-height: 1.48; }\n\ndialog { width: min(430px, calc(100% - 32px)); border: 1px solid var(--line); border-radius: 19px; padding: 0; color: var(--ink); background: #18100a; box-shadow: 0 20px 80px rgba(0,0,0,.6); }\ndialog::backdrop { background: rgba(0,0,0,.6); backdrop-filter: blur(3px); }\n.dialogCard { position: relative; padding: 22px; }\n.dialogCard h2 { margin-bottom: 10px; }\n.dialogCard > p:not(.eyebrow) { color: var(--muted); line-height: 1.45; }\n.dialogHint { margin: 13px 0; }\n.dialogClose { position: absolute; top: 9px; right: 9px; width: 30px; height: 30px; border: 0; border-radius: 50%; color: var(--ink); background: rgba(255,255,255,.09); font-size: 21px; cursor: pointer; }\n\n@media (max-width: 720px) {\n  .appShell { padding-inline: 10px; }\n  .workspace { grid-template-columns: 1fr; min-height: 68dvh; }\n  .filePane { max-height: 31dvh; border-right: 0; border-bottom: 1px solid var(--line); }\n  .heroGlyph { display: none; }\n  .summary { display: grid; grid-template-columns: 1fr 1fr; }\n}\n\n@media (max-width: 470px) {\n  .topbar { align-items: flex-start; }\n  .titleBlock { text-align: left; }\n  .topbar > .quietButton { display: none; }\n  .backLink { min-height: 34px; padding: 6px 8px; }\n  .editorHead { align-items: flex-start; flex-direction: column; }\n  .editorActions { width: 100%; }\n  .editorActions > * { flex: 1; }\n}\n"
