    "content": "\"use strict\";\n\nconst CACHE = \"cht360-offline-dilna-v1\";\nconst FILES = [\n  \"./\",\n  \"./index.html\",\n  \"./styles.css\",\n  \"./app.js\",\n  \"./manifest.webmanifest\",\n  \"./vendor/fflate-0.8.2.min.js\"\n];\n\nself.addEventListener(\"install\", event => {\n  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(FILES)).then(() => self.skipWaiting()));\n});\n\nself.addEventListener(\"activate\", event => {\n  event.waitUntil(\n    caches.keys()\n      .then(keys => Promise.all(keys.filter(key => key.startsWith(\"cht360-offline-dilna-\") && key !== CACHE).map(key => caches.delete(key))))\n      .then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener(\"fetch\", event => {\n  if (event.request.method !== \"GET\") return;\n  const url = new URL(event.request.url);\n  if (url.origin !== self.location.origin) return;\n\n  event.respondWith(\n    caches.match(event.request, { ignoreSearch: true })\n      .then(found => found || fetch(event.request).then(response => {\n        if (response && response.ok) {\n          const copy = response.clone();\n          caches.open(CACHE).then(cache => cache.put(event.request, copy));\n        }\n        return response;\n      }))\n      .catch(() => caches.match(\"./index.html\"))\n  );\n});\n"
