    "content": ":root{\n  color-scheme:dark;\n  --bg:#050504;\n  --gold:#c79b33;\n  --gold-light:#ffe2ad;\n  --gold-pale:#fff0c5;\n  --muted:#a49d90;\n  --line:rgba(255,226,173,.22);\n  --line-strong:rgba(255,226,173,.56);\n  --danger:#f08d78;\n  font-family:system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n}\n\n*{box-sizing:border-box}\n\nhtml,body{\n  margin:0;\n  width:100%;\n  min-height:100%;\n  background:#050504;\n}\n\nbody{\n  min-height:100dvh;\n  overflow:hidden;\n  color:var(--gold-pale);\n  background:\n    radial-gradient(circle at 50% 17%,rgba(147,104,33,.16),transparent 35%),\n    radial-gradient(circle at 50% 100%,rgba(70,61,40,.18),transparent 44%),\n    #050504;\n}\n\nbutton,input,select,textarea{\n  font:inherit;\n}\n\nbutton{\n  -webkit-tap-highlight-color:transparent;\n}\n\n.app-shell{\n  width:100%;\n  min-height:100dvh;\n  display:grid;\n  grid-template-rows:auto minmax(0,1fr) auto;\n}\n\n.topbar{\n  z-index:3;\n  display:grid;\n  grid-template-columns:minmax(140px,1fr) auto minmax(100px,1fr);\n  align-items:center;\n  gap:14px;\n  padding:max(14px,env(safe-area-inset-top)) clamp(14px,2.6vw,32px) 14px;\n  border-bottom:1px solid rgba(255,226,173,.09);\n  background:linear-gradient(180deg,rgba(5,5,4,.94),rgba(5,5,4,.55));\n  backdrop-filter:blur(12px);\n}\n\n.brand{\n  color:inherit;\n  text-decoration:none;\n  display:inline-flex;\n  align-items:center;\n  gap:9px;\n}\n\n.brand-mark{\n  display:grid;\n  place-items:center;\n  width:31px;\n  height:31px;\n  border:1px solid var(--line-strong);\n  border-radius:50%;\n  color:var(--gold-light);\n  box-shadow:inset 0 0 16px rgba(199,155,51,.16),0 0 15px rgba(199,155,51,.14);\n}\n\n.brand strong,\n.brand small{\n  display:block;\n  line-height:1.08;\n}\n\n.brand strong{\n  font-size:13px;\n  letter-spacing:.075em;\n}\n\n.brand small{\n  color:var(--muted);\n  font-size:10px;\n  margin-top:3px;\n}\n\n.core-pills{\n  display:flex;\n  flex-wrap:wrap;\n  justify-content:center;\n  gap:7px;\n}\n\n.core-pill{\n  cursor:pointer;\n  color:var(--muted);\n  display:inline-flex;\n  align-items:baseline;\n  gap:6px;\n  padding:6px 9px;\n  border:1px solid rgba(255,226,173,.12);\n  border-radius:999px;\n  background:rgba(255,255,255,.025);\n}\n\n.core-pill span{\n  font-size:9px;\n  letter-spacing:.08em;\n}\n\n.core-pill b{\n  font-size:10px;\n}\n\n.core-pill.active{\n  color:var(--gold-pale);\n  border-color:var(--gold);\n  background:rgba(199,155,51,.14);\n  box-shadow:0 0 18px rgba(199,155,51,.12);\n}\n\n.top-actions{\n  justify-self:end;\n  display:flex;\n  gap:8px;\n}\n\n.icon-button,\n.close-button{\n  border:1px solid var(--line);\n  color:var(--gold-light);\n  background:rgba(255,255,255,.025);\n  cursor:pointer;\n}\n\n.icon-button{\n  width:33px;\n  height:33px;\n  border-radius:50%;\n  font-size:17px;\n}\n\n.tower-stage{\n  min-height:0;\n  position:relative;\n  overflow:hidden;\n}\n\n#towerCanvas{\n  width:100%;\n  height:100%;\n  display:block;\n  touch-action:none;\n}\n\n.stage-label{\n  pointer-events:none;\n  position:absolute;\n  top:18px;\n  left:50%;\n  transform:translateX(-50%);\n  text-align:center;\n  text-shadow:0 2px 16px #000;\n}\n\n.stage-label span{\n  display:block;\n  color:var(--gold-light);\n  font-size:12px;\n  font-weight:700;\n  letter-spacing:.22em;\n}\n\n.stage-label small{\n  display:block;\n  margin-top:4px;\n  color:var(--muted);\n  font-size:10px;\n  white-space:nowrap;\n}\n\n.legend{\n  pointer-events:none;\n  position:absolute;\n  bottom:17px;\n  left:clamp(14px,2.6vw,32px);\n  display:flex;\n  gap:12px;\n  color:rgba(255,240,197,.75);\n  font-size:10px;\n}\n\n.bottom-bar{\n  z-index:2;\n  display:flex;\n  gap:18px;\n  justify-content:space-between;\n  align-items:center;\n  padding:11px clamp(14px,2.6vw,32px) max(11px,env(safe-area-inset-bottom));\n  border-top:1px solid rgba(255,226,173,.09);\n  background:rgba(5,5,4,.8);\n}\n\n.bottom-bar p{\n  margin:0;\n  font-size:10px;\n}\n\n#status{\n  color:var(--gold-light);\n}\n\n.gesture-help{\n  color:var(--muted);\n  text-align:right;\n}\n\n.modal[hidden]{\n  display:none;\n}\n\n.modal{\n  position:fixed;\n  inset:0;\n  z-index:10;\n  display:grid;\n  place-items:center;\n  padding:18px;\n}\n\n.modal-backdrop{\n  position:absolute;\n  inset:0;\n  background:rgba(0,0,0,.68);\n  backdrop-filter:blur(7px);\n}\n\n.modal-card{\n  position:relative;\n  z-index:1;\n  width:min(560px,100%);\n  max-height:min(720px,calc(100dvh - 36px));\n  display:grid;\n  grid-template-rows:auto minmax(0,1fr) auto;\n  overflow:hidden;\n  border:1px solid rgba(255,226,173,.55);\n  border-radius:23px;\n  background:linear-gradient(160deg,rgba(25,22,15,.985),rgba(9,9,8,.985));\n  box-shadow:0 24px 70px rgba(0,0,0,.7),0 0 34px rgba(199,155,51,.15);\n}\n\n.modal-header{\n  display:flex;\n  justify-content:space-between;\n  gap:14px;\n  align-items:center;\n  padding:20px 22px 16px;\n  border-bottom:1px solid var(--line);\n}\n\n.eyebrow{\n  margin:0 0 5px;\n  color:var(--gold);\n  font-size:10px;\n  letter-spacing:.15em;\n  font-weight:700;\n}\n\n.modal-header h1{\n  margin:0;\n  color:var(--gold-pale);\n  font-size:19px;\n}\n\n.close-button{\n  display:grid;\n  place-items:center;\n  width:32px;\n  height:32px;\n  border-radius:50%;\n  font-size:23px;\n}\n\n.modal-body{\n  overflow:auto;\n  display:grid;\n  align-content:start;\n  gap:15px;\n  padding:18px 22px;\n}\n\nlabel{\n  display:grid;\n  gap:7px;\n  color:var(--gold-light);\n  font-size:11px;\n  font-weight:650;\n}\n\ninput,select,textarea{\n  width:100%;\n  color:var(--gold-pale);\n  border:1px solid rgba(255,226,173,.18);\n  border-radius:11px;\n  outline:none;\n  background:rgba(255,255,255,.045);\n  padding:10px 11px;\n  font-size:14px;\n}\n\ninput:focus,\nselect:focus,\ntextarea:focus{\n  border-color:var(--gold);\n  background:rgba(199,155,51,.08);\n}\n\ntextarea{\n  min-height:144px;\n  resize:vertical;\n  line-height:1.45;\n}\n\ninput[type=\"color\"]{\n  height:41px;\n  padding:4px;\n}\n\n.form-row{\n  display:grid;\n  grid-template-columns:minmax(0,1fr) 74px 66px;\n  gap:10px;\n}\n\n.budget{\n  margin:-7px 0 0;\n  color:var(--muted);\n  font-size:10px;\n}\n\n.modal-actions{\n  display:flex;\n  align-items:center;\n  gap:9px;\n  padding:15px 22px max(17px,env(safe-area-inset-bottom));\n  border-top:1px solid var(--line);\n}\n\n.action-spacer{\n  flex:1;\n}\n\n.button{\n  min-height:37px;\n  border-radius:11px;\n  padding:0 13px;\n  font-weight:700;\n  font-size:12px;\n  cursor:pointer;\n}\n\n.button.primary{\n  color:#211506;\n  border:1px solid #f6cb78;\n  background:linear-gradient(135deg,#f5d28e,#c79b33);\n}\n\n.button.ghost{\n  color:var(--gold-light);\n  border:1px solid var(--line);\n  background:rgba(255,255,255,.025);\n}\n\n.button.danger{\n  color:var(--danger);\n}\n\n@media(max-width:780px){\n  .topbar{\n    grid-template-columns:1fr auto;\n    gap:11px;\n  }\n\n  .core-pills{\n    grid-column:1 / -1;\n    grid-row:2;\n    justify-content:flex-start;\n    flex-wrap:nowrap;\n    overflow-x:auto;\n  }\n\n  .core-pill{\n    flex:0 0 auto;\n  }\n\n  .top-actions{\n    grid-column:2;\n    grid-row:1;\n  }\n\n  .bottom-bar{\n    align-items:flex-start;\n    flex-direction:column;\n    gap:4px;\n  }\n\n  .gesture-help{\n    text-align:left;\n  }\n}\n\n@media(max-width:470px){\n  .brand small,\n  .legend{\n    display:none;\n  }\n\n  .form-row{\n    grid-template-columns:minmax(0,1fr) 63px 58px;\n  }\n\n  .modal{\n    padding:8px;\n  }\n\n  .modal-card{\n    max-height:calc(100dvh - 16px);\n    border-radius:19px;\n  }\n\n  .modal-header,\n  .modal-body,\n  .modal-actions{\n    padding-left:16px;\n    padding-right:16px;\n  }\n}\n"
