      "mod",
      "allNav",
      "allQuick",
      "currentModuleId",
      "url",
      "pill",
      "lastId",
      "modIds",
      "currentId",
      "idx",
      "nextId",
      "vaftToggleEl",
      "vaftToggleLabelEl",
      "vaftPanelEl",
      "vaftMessagesEl",
      "vaftInputEl",
      "vaftSendBtnEl",
      "vaftModuleTagEl",
      "vaftPanelSubEl",
      "VAFT_HISTORY_KEY",
      "raw",
      "parsed",
      "vaftHistory",
      "span",
