      "modName",
      "replies",
      "replyText",
      "isOpen",
      "sidebar-left",
      "main-title",
      "main-subtitle",
      "main-tags",
      "module-frame",
      "main-placeholder",
      "quick-list",
      "vaft-toggle",
      "vaft-toggle-label",
