    "content": "*{\n    margin:0;\n    padding:0;\n    box-sizing:border-box;\n}\n\nbody{\n    background:#0f1117;\n    color:white;\n    font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",sans-serif;\n    min-height:100vh;\n}\n\n.app{\n    padding:30px;\n}\n\n#splash{\n    position:fixed;\n    inset:0;\n    background:#0f1117;\n\n    display:flex;\n    flex-direction:column;\n    justify-content:center;\n    align-items:center;\n\n    z-index:9999;\n\n    transition:opacity 1s;\n}\n\n.splash-symbol{\n    font-size:30px;\n    color:#8cffb0;\n\n    animation:fadeIn 2s ease;\n}\n\n.splash-title{\n    margin-top:20px;\n\n    font-size:32px;\n    font-weight:700;\n\n    animation:fadeIn 2.5s ease;\n}\n\n.splash-loading{\n    margin-top:15px;\n\n    color:#9aa3b2;\n\n    animation:pulse 1.5s infinite;\n}\n\n@keyframes fadeIn{\n\n    from{\n        opacity:0;\n        transform:translateY(20px);\n    }\n\n    to{\n        opacity:1;\n        transform:translateY(0);\n    }\n\n}\n\n@keyframes pulse{\n\n    0%{\n        opacity:.3;\n    }\n\n    50%{\n        opacity:1;\n    }\n\n    100%{\n        opacity:.3;\n    }\n\n}\n\n.core-frame{\n    position:absolute;\n    inset:0;\n\n    width:100%;\n    height:100%;\n\n    border:none;\n\n    pointer-events:none;\n}\n\n.splash-overlay{\n    position:absolute;\n    inset:0;\n\n    display:flex;\n    flex-direction:column;\n    justify-content:flex-end;\n    align-items:center;\n\n    padding-bottom:120px;\n\n    z-index:10;\n}\n\n.splash-title{\n    font-size:34px;\n    font-weight:700;\n\n    color:white;\n\n    text-shadow:\n        0 0 20px rgba(255,210,150,.4);\n}\n\n.splash-subtitle{\n    margin-top:10px;\n\n    letter-spacing:4px;\n\n    color:#d4aa62;\n\n    font-size:12px;\n}"
