      "globalTiltY",
      "targetTiltX",
      "targetTiltY",
      "orbitRotation",
      "orbitVelocity",
      "orbitDamping",
      "orbitBaseDrift",
      "orbitNudgeX",
      "orbitNudgeY",
      "activeSphere",
