    "content": ":root {\n  --bg: radial-gradient(circle at top, #020617 0%, #010814 40%, #000 100%);\n  --card: rgba(2,6,23,.6);\n  --line: rgba(148,163,184,.03);\n  --txt: #e2e8f0;\n  --accent: #38bdf8;\n}\n* { box-sizing:border-box; }\nbody {\n  margin:0;\n  min-height:100vh;\n  background:var(--bg);\n  color:var(--txt);\n  font-family:-apple-system,system-ui,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  padding-bottom:90px;\n}\n.topbar {\n  padding:16px 16px 0;\n  display:flex;\n  justify-content:space-between;\n  gap:12px;\n  align-items:center;\n}\n.brand-block { display:flex; flex-direction:column; gap:2px; }\n.brand-mini { font-size:.58rem; opacity:.5; }\n.brand-title { font-size:1.15rem; font-weight:600; }\n.role-badge {\n  background:rgba(59,130,246,.08);\n  border:1px solid rgba(59,130,246,.35);\n  border-radius:999px;\n  padding:3px 10px 4px;\n  font-size:.62rem;\n}\n.coins {\n  background:rgba(15,23,42,.6);\n  border:1px solid rgba(148,163,184,.19);\n  border-radius:14px;\n  padding:6px 10px 5px;\n  display:flex;\n  gap:6px;\n  align-items:center;\n}\n.coin-icon {\n  width:22px;height:22px;border-radius:999px;\n  display:flex;align-items:center;justify-content:center;\n  background:radial-gradient(circle,#eab308 0%,#92400e 90%);\n  font-size:.6rem;\n}\n.coin-txt { line-height:1.1; font-size:.6rem; text-align:right; }\n.coin-ver { opacity:.4; }\n\n/* revia panel */\n.revia-panel {\n  margin:14px 16px 0;\n  background:rgba(2,6,23,.45);\n  border:1px solid rgba(148,163,184,.05);\n  border-radius:20px;\n  padding:10px 10px 16px;\n}\n.revia-head { display:flex; justify-content:space-between; align-items:center; }\n.revia-title { font-weight:500; }\n.revia-link { color:var(--accent); font-size:.68rem; }\n.rules {\n  margin-top:6px;\n  background:rgba(15,23,42,.35);\n  border:1px solid rgba(148,163,184,.1);\n  border-radius:12px;\n  padding:6px 8px;\n  font-size:.6rem;\n  width:fit-content;\n}\n.pulse-line {\n  margin-top:6px; display:inline-flex; gap:6px; align-items:center;\n  background:rgba(248,113,113,.04);\n  border:1px solid rgba(248,113,113,.12);\n  border-radius:999px;\n  padding:4px 9px;\n  font-size:.62rem;\n}\n.pulse-dot {\n  width:7px;height:7px;border-radius:999px;background:#f43f5e;\n  animation:blip 2s infinite;\n}\n@keyframes blip { 0%,100%{opacity:1} 50%{opacity:.2} }\n\n.center-orbit { position:relative; margin-top:18px; height:205px; }\n.vaft-core {\n  position:absolute;top:50%;left:50%;\n  width:130px;height:130px;margin-left:-65px;margin-top:-65px;\n  border:1px solid rgba(56,189,248,.4);\n  border-radius:999px;\n  display:flex;align-items:center;justify-content:center;text-align:center;\n  font-size:.62rem;\n  animation:spin 12s linear infinite;\n}\n@keyframes spin { 0%{transform:rotate(0)} 100%{transform:rotate(360deg)} }\n.orbit-node {\n  position:absolute;width:70px;height:70px;border-radius:999px;\n  border:1px solid rgba(126,248,156,.48);\n  background:rgba(15,23,42,.15);\n  display:flex;align-items:center;justify-content:center;font-size:.58rem;\n}\n.node-glyph { left:10px; bottom:6px; }\n.node-ai { right:14px; top:12px; }\n.node-world { right:16px; bottom:12px; }\n\n/* tabs */\n.tabs { margin:10px 16px 0; display:flex; gap:8px; }\n.tab-btn {\n  flex:1; background:rgba(15,23,42,.08); border-radius:14px; padding:6px 7px 7px;\n  text-align:center; font-size:.7rem; color:#e2e8f0; border:1px solid transparent;\n}\n.tab-btn.active {\n  background:linear-gradient(140deg,#22c55e,#06b6d4);\n  border:1px solid rgba(255,255,255,.04);\n  color:#fff;\n}\n\n/* panel */\n.panel {\n  margin:10px 16px 0;\n  background:rgba(2,6,23,.55);\n  border:1px solid rgba(148,163,184,.03);\n  border-radius:16px;\n  padding:10px 10px 14px;\n  display:none;\n}\n.panel.active { display:block; }\n.panel-title { font-weight:600;margin-bottom:8px; }\n.label-sm { font-size:.6rem;opacity:.55; }\n.hero-input, .hero-select {\n  width:100%; background:rgba(15,23,42,.5); border:1px solid rgba(148,163,184,.12);\n  border-radius:10px; padding:6px 8px; color:#fff; font-size:.7rem; margin-bottom:7px;\n}\n.btn-primary {\n  background:#0ea5e9; border:none; border-radius:999px; color:#fff;\n  padding:6px 12px; font-size:.7rem; font-weight:500;\n}\n.list-sm { margin-top:8px;font-size:.6rem;opacity:.6; }\n\n/* chat */\n#hlavoun-chat {\n  background:rgba(1,4,10,.3);\n  border:1px solid rgba(148,163,184,.03);\n  border-radius:12px;\n  padding:8px;\n  max-height:195px;\n  overflow-y:auto;\n  display:flex;\n  flex-direction:column;\n  gap:6px;\n  font-size:.64rem;\n}\n.chat-row { display:flex; gap:6px; margin-top:8px; }\n.chat-row input {\n  flex:1; background:rgba(15,23,42,.4); border:1px solid rgba(148,163,184,.12);\n  border-radius:9px; padding:5px 7px; color:#fff; font-size:.65rem;\n}\n.chat-row button {\n  background:#0ea5e9; border:none; border-radius:9px; padding:5px 10px; color:#fff; font-size:.65rem;\n}\n.quick-row { display:flex; gap:6px; margin-top:6px; flex-wrap:wrap; }\n.quick-row button {\n  background:rgba(14,165,233,.2); border:1px solid rgba(14,165,233,.1);\n  border-radius:8px; padding:3px 8px; font-size:.6rem; color:#e2e8f0;\n}\n\n/* systém */\n.apps-wrap { margin-top:6px; border:1px solid rgba(148,163,184,.03); border-radius:14px; overflow:hidden; }\n.app-row { padding:8px 9px; border-bottom:1px solid rgba(148,163,184,.03); }\n.app-row:last-child { border-bottom:none; }\n.app-name { font-size:.75rem; }\n.app-desc { font-size:.58rem; opacity:.45; }\n.app-btn {\n  background:rgba(56,189,248,.12); border:1px solid rgba(56,189,248,.04);\n  border-radius:8px; padding:4px 10px; color:#fff; font-size:.62rem; margin-top:4px;\n}\n\n/* panely – jen jeden je vidět */\n.panel {\n  display: none;\n}\n\n.panel.active {\n  display: block;\n  animation: vaftFade .15s ease-out;\n}\n\n@keyframes vaftFade {\n  from { opacity: 0; transform: translateY(4px); }\n  to   { opacity: 1; transform: translateY(0); }\n}\n\n/* můžeš dát do style.css */\n.pill-container {\n  display: flex;\n  flex-wrap: wrap;\n  gap: .5rem;\n}\n\n.pill {\n  background: rgba(255,255,255,0.03);\n  border: 1px solid rgba(255,255,255,0.05);\n  border-radius: 14px;\n  padding: 6px 10px;\n  display: flex;\n  gap: .4rem;\n  align-items: center;\n  cursor: pointer;\n  backdrop-filter: blur(3px);\n}\n\n.pill:hover {\n  background: rgba(255,255,255,0.08);\n}\n\n.pill-code {\n  background: rgba(0,0,0,0.3);\n  border-radius: 999px;\n  padding: 2px 6px;\n  font-size: 11px;\n}\n\n.vafit-row {\n  display: flex;\n  gap: .6rem;\n  align-items: center;\n  background: rgba(255,255,255,0.02);\n  border: 1px solid rgba(255,255,255,0.03);\n  border-radius: 10px;\n  padding: 6px 8px;\n  min-width: 190px;\n}\n\n.vafit-glyph {\n  font-family: \"SF Mono\", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", \"Courier New\", monospace;\n  font-size: 14px;\n}\n\n.vafit-role {\n  opacity: .5;\n  font-size: 11px;\n}\n"
