    "content": ":root {\n  --bg: #020202;\n  --panel: rgba(7,7,8,.65);\n  --line: rgba(255,255,255,.08);\n  --text: #e8f4ff;\n  --accent: #9cf;\n}\n* { box-sizing: border-box; }\nbody {\n  margin: 0;\n  background: radial-gradient(circle at top, #111 0%, #000 55%, #000 100%);\n  color: var(--text);\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  min-height: 100vh;\n}\n#app {\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n}\n.topbar {\n  backdrop-filter: blur(10px);\n  background: rgba(0,0,0,.35);\n  border-bottom: 1px solid rgba(255,255,255,.04);\n  padding: 10px 14px 6px;\n}\n.title {\n  font-weight: 600;\n  letter-spacing: .05em;\n  font-size: 14px;\n}\n.letter-bar {\n  margin-top: 6px;\n  font-size: 13px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n.letter-pill {\n  background: rgba(156, 200, 255, 0.08);\n  border: 1px solid rgba(156, 200, 255, 0.3);\n  border-radius: 999px;\n  padding: 2px 7px 1px;\n  font-weight: 500;\n}\n.layout {\n  display: flex;\n  gap: 14px;\n  padding: 10px;\n  flex: 1;\n}\nsection {\n  background: var(--panel);\n  border: 1px solid rgba(255,255,255,.03);\n  border-radius: 14px;\n  padding: 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.nodes { flex: 1; min-width: 38%; }\n.lab { flex: 1; }\nh2 { font-size: 14px; margin: 0; }\n.hint { margin: 0; font-size: 12px; opacity: .7; }\n.node-list, .recipe-list { display: flex; flex-direction: column; gap: 6px; }\n.node {\n  background: rgba(0,0,0,.25);\n  border: 1px solid rgba(255,255,255,.03);\n  border-radius: 9px;\n  padding: 6px 8px;\n  cursor: pointer;\n  transition: .15s;\n  display: flex;\n  justify-content: space-between;\n  gap: 8px;\n  align-items: center;\n}\n.node:hover { background: rgba(10, 62, 120, 0.2); }\n.node small { opacity: .6; font-size: 11px; }\n.recipe {\n  background: rgba(0,0,0,.25);\n  border: 1px solid rgba(255,255,255,.03);\n  border-radius: 9px;\n  padding: 6px 8px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.recipe button {\n  background: rgba(156, 200, 255, .09);\n  border: 1px solid rgba(156, 200, 255, .3);\n  border-radius: 6px;\n  padding: 3px 7px;\n  color: var(--text);\n  font-size: 12px;\n  align-self: flex-start;\n}\n.recipe button:disabled { opacity: .4; }\n.lab-log { min-height: 42px; font-size: 11px; opacity: 0.7; }\n@media (max-width: 880px) {\n  .layout { flex-direction: column; }\n}\n"
