    "content": ":root {\n  --bg: #000;\n  --panel: rgba(0,0,0,.35);\n  --line: rgba(255,255,255,.03);\n  --text: #e8f4ff;\n}\n\nbody {\n  margin: 0;\n  background: #000;\n  color: var(--text);\n  font-family: system-ui, -apple-system, sans-serif;\n  min-height: 100vh;\n  display: flex;\n  justify-content: center;\n}\n\n#app {\n  width: 100%;\n  max-width: 540px;\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n}\n\n.topbar {\n  padding: 10px 14px 6px;\n  background: rgba(0,0,0,.65);\n  backdrop-filter: blur(10px);\n  border-bottom: 1px solid rgba(255,255,255,.04);\n}\n\n.title {\n  font-size: 14px;\n  font-weight: 600;\n}\n\n.subtitle {\n  font-size: 11px;\n  opacity: .6;\n}\n\n#map {\n  flex: 1;\n  width: 100%;\n  background: radial-gradient(circle at center, #1b2735 0%, #090a0f 85%);\n  display: block;\n}\n\n.panel {\n  padding: 10px 14px 18px;\n  background: rgba(0,0,0,.4);\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.panel button {\n  background: rgba(166, 208, 255, 0.07);\n  border: 1px solid rgba(166, 208, 255, 0.3);\n  border-radius: 9px;\n  padding: 6px 10px;\n  color: #fff;\n  font-size: 12px;\n}\n"
