    "content": "{\n  \"name\": \"VAFT-StarSkull\",\n  \"short_name\": \"StarSkull\",\n  \"description\": \"VAFT-StarSkull - Progressive Web App\",\n  \"start_url\": \"./index.html\",\n  \"scope\": \"./\",\n  \"display\": \"standalone\",\n  \"theme_color\": \"#0a0e1f\",\n  \"background_color\": \"#1a1a2e\",\n  \"icons\": [\n    {\"src\": \"./icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\"},\n    {\"src\": \"./icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\"}\n  ]\n}\n"
